fn solve(n: i8, s: Vec<char>) -> i8 {
    let mut x = 0;
    let mut y = 0;
    let mut region: Option<char> = None; // None = border, Some('A') = region A, Some('B') = region B
    let mut transitions = 0;
    
    for &c in &s {
        // Apply move
        match c {
            'U' => y += 1,
            'R' => x += 1,
            _ => {} // According to problem, only 'U' or 'R' appear
        }
        
        // Determine current region
        let current_region = if x > y {
            Some('A')
        } else if y > x {
            Some('B')
        } else {
            None
        };
        
        // Check for transition
        if let Some(current) = current_region {
            if let Some(prev) = region {
                // We were in a region before (not border)
                if current != prev {
                    transitions += 1;
                }
            }
            // Update region
            region = Some(current);
        } else {
            // We're on border - region stays as whatever it was before
            // (don't update region when on border)
        }
    }
    
    transitions
}